describe('User Mention in Comment', () => {
  beforeEach(() => {
    cy.visit('/comments');
  });

  it('should successfully mention another user in a comment', () => {
    // Setup: Navigate to comment section
    cy.get('[data-testid="comment-input"]').should('be.visible');

    // Type comment with mention
    cy.get('[data-testid="comment-input"]').type('Hey @john_doe, can you review this?');

    // Verify mention is formatted correctly
    cy.get('[data-testid="mention-tag"]').should('contain', '@john_doe');
    cy.get('[data-testid="mention-tag"]').should('have.class', 'mention-formatted');

    // Verify mention has a tooltip or preview
    cy.get('[data-testid="mention-tag"]').should('be.visible');
    cy.get('[data-testid="mention-tag"]').should('contain', 'john_doe');

    // Submit comment
    cy.get('[data-testid="submit-comment-button"]').click();

    // Verify comment is posted
    cy.get('[data-testid="comment-list"]').should('contain', 'Hey @john_doe, can you review this?');

    // Verify mention is visible in comment
    cy.get('[data-testid="comment-item"]').should('contain', '@john_doe');

    // Verify mention is clickable and links to user profile
    cy.get('[data-testid="mention-tag"]').should('be.visible');
    cy.get('[data-testid="mention-tag"]').should('have.attr', 'href');
    cy.get('[data-testid="mention-tag"]').should('have.attr', '/users/john_doe');
  });

  it('should handle invalid or non-existent user mentions', () => {
    // Setup: Navigate to comment section
    cy.get('[data-testid="comment-input"]').should('be.visible');

    // Type comment with invalid mention
    cy.get('[data-testid="comment-input"]').type('Hey @invaliduser123, please check this out');

    // Verify mention is not formatted as a valid user
    cy.get('[data-testid="mention-tag"]').should('not.exist');

    // Verify no mention preview appears
    cy.get('[data-testid="mention-preview"]').should('not.exist');

    // Submit comment
    cy.get('[data-testid="submit-comment-button"]').click();

    // Verify comment is posted without mention
    cy.get('[data-testid="comment-list"]').should('contain', 'Hey invaliduser123, please check this out');

    // Verify mention is not clickable
    cy.get('[data-testid="comment-item"]').should('not.contain', '[data-testid="mention-tag"]');

    // Verify error message for invalid mention is displayed
    cy.get('[data-testid="mention-error-message"]').should('be.visible');
    cy.get('[data-testid="mention-error-message"]').should('contain', 'User not found');
  });
});
